// UnassignedEntry An entry of No asignados: a first-level folder of `_unassigned/`, or a loose file (RF-08, RF-27).
// Its `id` is its id in the registry and stays while the entry is in No asignados.
type UnassignedEntry struct {
	Files []UnassignedFile `json:"files"`
	Id    int64            `json:"id"`

	// Loose A single file kept as it is. Its only file is the entry itself.
	Loose bool `json:"loose"`

	// Name The name of the folder or of the loose file, with its extension.
	Name string `json:"name"`

	// Origin `upload` when the ingestion moved it in (RF-08), `samba` when Samba copied it (RF-27).
	Origin UnassignedEntryOrigin `json:"origin"`

	// Relation How the files of a batch relate (RF-03): `parts` for parts of one film or
	// series, `episodes` for chapters of one series, `none` for no relation.
	Relation BatchRelation `json:"relation"`

	// Size The total size of its files, junk not counted.
	Size int64 `json:"size"`

	// Status `copying` while a file is still being copied, which takes precedence; `assigning` while an
	// assignment holds the entry (RF-26); `ready` otherwise.
	Status UnassignedEntryStatus `json:"status"`
}

// UnassignedEntryOrigin `upload` when the ingestion moved it in (RF-08), `samba` when Samba copied it (RF-27).
type UnassignedEntryOrigin string

// UnassignedEntryStatus `copying` while a file is still being copied, which takes precedence; `assigning` while an
// assignment holds the entry (RF-26); `ready` otherwise.
type UnassignedEntryStatus string

// UnassignedFile A file of an entry, with its size and whether it is still being copied (RF-27).
type UnassignedFile struct {
	Copying bool `json:"copying"`

	// Path Its place inside the entry, with "/" separators (a subfolder's files have one). Empty for a loose
	// entry, whose file is the entry itself.
	Path string `json:"path"`
	Size int64  `json:"size"`
}

// UnassignedFileRequest The file of an entry that a change applies to, by its place inside the entry.
type UnassignedFileRequest struct {
	// Path The place of the file inside the entry, as the section listed it. Names are checked on the
	// server: no empty name, no `.` or `..`, no separator in a name, no control character.
	Path string `json:"path"`
}

// UnassignedSection The entries of No asignados, as the disk holds them now (RF-27), and the jobs of the compressed files Samba copied (RF-27a).
type UnassignedSection struct {
	Entries []UnassignedEntry `json:"entries"`

	// Jobs The jobs of the compressed files that Samba copied into `_unassigned/` (RF-27a), one per unit: the
	// job of the first volume of a set. A job is listed while its content has not reached No asignados,
	// the trash or a cancellation; a failed one stays listed, with its reason, so that its password or
	// its retry can be sent, until it is taken off with `POST /jobs/{id}/dismiss`. Each item is the object
	// `GET /jobs` lists, with the same `id`.
	Jobs []UploadJob `json:"jobs"`
}

// UploadJob One uploaded file and its state (RF-10a, RF-10b).
type UploadJob struct {
	Batch     Batch     `json:"batch"`
	CreatedAt time.Time `json:"createdAt"`

	// Error Stable reason of a job (RF-10b, RF-10c). The UI translates it with i18n
	// keys. A `failed` job gives its reason here:
	// `upload_abandoned`: the upload had no activity for 24 hours and its
	// partial file was deleted, so the file must be uploaded again.
	// `upload_missing`: the job was still uploading, but its file is no longer
	// in staging.
	// `no_space`: the library has no room to extract (1 GiB margin, RF-05).
	// `archive_corrupt`: the archive is damaged or 7-Zip failed on it.
	// `crc_mismatch`: an extracted file does not match the size or CRC32 of the
	// archive index (RF-05).
	// `archive_unsafe`: the archive has paths outside its folder or links.
	// `parts_mismatch`: the volumes do not form one multi-volume archive.
	// `parts_missing`: some volumes did not arrive within 24 hours.
	// `legacy_volume`: an old-style RAR volume (`.r00`, `.r01`…), which is not supported.
	// `no_video`: after filtering nothing is left to keep, neither a video nor a subtitle (RF-07).
	// `filter_failed`: reading or writing the staging area failed while filtering (RF-07, RF-08a).
	// `move_failed`: reading or writing the library failed while moving the content to No asignados (RF-08a).
	// `trash_failed`: the original of the archive did not reach the trash after its extraction; it stays in staging
	// and nothing is deleted (RF-08a).
	// `no_space`, `archive_corrupt` and `crc_mismatch` can be retried, and so can `filter_failed`, `move_failed` and
	// `trash_failed`; the others cannot (`legacy_volume` and `no_video` among them). A job in `needs_password` gives `wrong_password` here when
	// the password it was sent did not open the archive.
	Error *JobFailure `json:"error,omitempty"`

	// FileName File name, without folders.
	FileName string `json:"fileName"`

	// Id Job id. It is also the id of the tus upload (the last segment of its `Location`).
	//
	// Example: 3kQ7Zr1xVb8mNcT2pL0aWq
	Id string `json:"id"`

	// Progress Percentage extracted while the job is `extracting` (RF-10); 0 in other states, 100 once the archive is extracted.
	Progress int `json:"progress"`

	// Received Bytes that arrived so far. Equals `size` once the job is `uploaded`.
	Received int64 `json:"received"`

	// RelativePath Path inside the folder dropped in the browser (RF-01a), ending with `fileName`. Empty for a file dropped on its own.
	RelativePath string `json:"relativePath"`

	// Size Bytes the upload declared.
	Size int64 `json:"size"`

	// Status State of an upload job (RF-10a). `uploading` while the bytes arrive and
	// `uploaded` once they all arrived. An archive then goes to `extracting`
	// (or `needs_password`, which waits for `POST /jobs/{id}/password`) and,
	// when it is extracted, to `filtering` (the filtering comes in a later
	// phase). A volume of a multi-volume archive waits in `waiting_parts` until its set is
	// complete, then the whole set is extracted together from its first volume;
	// `done` is reached by a later phase. `discarded` (RF-07) ends a job whose
	// content the filter discarded entirely while its batch keeps something; its
	// files are in the trash. `failed`
	// gives its reason in `error`; a failed job may move back to `extracting`
	// with `POST /jobs/{id}/retry`. `cancelled` ends the job.
	Status    JobStatus `json:"status"`
	UpdatedAt time.Time `json:"updatedAt"`
}

