// ServerInterface represents all server handlers.
type ServerInterface interface {
	// Login Start a session with the shared password
	// (POST /auth/login)
	Login(w http.ResponseWriter, r *http.Request)
	// Logout End the session on this device
	// (POST /auth/logout)
	Logout(w http.ResponseWriter, r *http.Request)
	// GetSession Current session
	// (GET /auth/session)
	GetSession(w http.ResponseWriter, r *http.Request)
	// CreateBatch Start a batch of files dropped together
	// (POST /batches)
	CreateBatch(w http.ResponseWriter, r *http.Request)
	// GetHealth Liveness probe and startup diagnostics
	// (GET /health)
	GetHealth(w http.ResponseWriter, r *http.Request)
	// GetImage Title image served from the local cache
	// (GET /images/{kind}/{file})
	GetImage(w http.ResponseWriter, r *http.Request, kind ImageKind, file string)
	// ListJobs Most recent upload jobs
	// (GET /jobs)
	ListJobs(w http.ResponseWriter, r *http.Request)
	// StreamJobEvents Live upload job changes (server-sent events, RF-10b)
	// (GET /jobs/events)
	StreamJobEvents(w http.ResponseWriter, r *http.Request)
	// DismissJob Take a failed Samba copy off No asignados ("Quitar")
	// (POST /jobs/{id}/dismiss)
	DismissJob(w http.ResponseWriter, r *http.Request, id JobId)
	// SubmitJobPassword Send the password of an encrypted archive
	// (POST /jobs/{id}/password)
	SubmitJobPassword(w http.ResponseWriter, r *http.Request, id JobId)
	// RetryJob Retry a job that failed for a retryable reason
	// (POST /jobs/{id}/retry)
	RetryJob(w http.ResponseWriter, r *http.Request, id JobId)
	// ListLibraryTitles The titles of the library (RF-40, RF-43)
	// (GET /library/titles)
	ListLibraryTitles(w http.ResponseWriter, r *http.Request)
	// GetLibraryTitle A title of the library with its files and TMDB details (RF-43, RF-43a)
	// (GET /library/titles/{id})
	GetLibraryTitle(w http.ResponseWriter, r *http.Request, id TitleId)
	// DownloadLibraryTitle Download a whole library title as a streamed store zip (RF-44)
	// (GET /library/titles/{id}/download)
	DownloadLibraryTitle(w http.ResponseWriter, r *http.Request, id TitleId)
	// CommitTitleEdit Store the edit of a title as one change of the library (RF-44)
	// (POST /library/titles/{id}/edit/commit)
	CommitTitleEdit(w http.ResponseWriter, r *http.Request, id TitleId)
	// PlanTitleEdit Preview the edit of a title, with its new name, its folder and where each file goes (RF-44)
	// (POST /library/titles/{id}/edit/plan)
	PlanTitleEdit(w http.ResponseWriter, r *http.Request, id TitleId)
	// DownloadLibraryFile Download one library file with HTTP Range support (RF-44)
	// (GET /library/titles/{id}/files/{fileId}/download)
	DownloadLibraryFile(w http.ResponseWriter, r *http.Request, id TitleId, fileId LibraryFileId)
	// GetLibraryFileTechnical Technical information of a library video (RF-44)
	// (GET /library/titles/{id}/files/{fileId}/technical)
	GetLibraryFileTechnical(w http.ResponseWriter, r *http.Request, id TitleId, fileId LibraryFileId)
	// CommitTitleIDTag Store the ID tag action of a title as one change of the library (RF-45)
	// (POST /library/titles/{id}/id-tag/commit)
	CommitTitleIDTag(w http.ResponseWriter, r *http.Request, id TitleId)
	// PlanTitleIDTag Preview putting the ID tag on a title or taking it off (RF-45)
	// (POST /library/titles/{id}/id-tag/plan)
	PlanTitleIDTag(w http.ResponseWriter, r *http.Request, id TitleId)
	// DownloadLibrarySeason Download one season of a library series as a streamed store zip (RF-44)
	// (GET /library/titles/{id}/seasons/{season}/download)
	DownloadLibrarySeason(w http.ResponseWriter, r *http.Request, id TitleId, season int)
	// TrashTitleScope Send a title, a season or a file to the trash, with its subtitles (RF-44, RF-30)
	// (POST /library/titles/{id}/trash)
	TrashTitleScope(w http.ResponseWriter, r *http.Request, id TitleId)
	// MoveTitleToUnassigned Move a title, a season or a file to No asignados, with its subtitles (RF-44)
	// (POST /library/titles/{id}/unassigned)
	MoveTitleToUnassigned(w http.ResponseWriter, r *http.Request, id TitleId)
	// GetScans The two scans of the library and when each last finished (RF-28)
	// (GET /scans)
	GetScans(w http.ResponseWriter, r *http.Request)
	// RunScans Scan now, both scans («Escanear ahora», RF-28)
	// (POST /scans)
	RunScans(w http.ResponseWriter, r *http.Request)
	// SearchTitles Titles to assign to, the library's first (RF-21)
	// (GET /titles/search)
	SearchTitles(w http.ResponseWriter, r *http.Request, params SearchTitlesParams)
	// EmptyTrash Permanently empty the trash (RF-30, RF-31a)
	// (DELETE /trash)
	EmptyTrash(w http.ResponseWriter, r *http.Request)
	// ListTrash List trash entries, newest first (RF-31a)
	// (GET /trash)
	ListTrash(w http.ResponseWriter, r *http.Request)
	// DeleteTrashEntry Permanently delete a trash entry (RF-30, RF-31a)
	// (DELETE /trash/{id})
	DeleteTrashEntry(w http.ResponseWriter, r *http.Request, id TrashId)
	// RestoreTrashEntry Restore an entry to its source (RF-31, RF-31a)
	// (POST /trash/{id}/restore)
	RestoreTrashEntry(w http.ResponseWriter, r *http.Request, id TrashId)
	// PlanTrashRestore Preview restoring an entry (RF-31, RF-31a)
	// (POST /trash/{id}/restore/plan)
	PlanTrashRestore(w http.ResponseWriter, r *http.Request, id TrashId)
	// GetUnassigned The entries of No asignados, read now from _unassigned/ (RF-27)
	// (GET /unassigned)
	GetUnassigned(w http.ResponseWriter, r *http.Request)
	// CommitAssign Store the assignment of an entry in the library (RF-25, RF-26)
	// (POST /unassigned/{id}/commit)
	CommitAssign(w http.ResponseWriter, r *http.Request, id EntryId, params CommitAssignParams)
	// DeleteUnassignedEntry Delete an entry of No asignados for good (RF-27, RF-30)
	// (POST /unassigned/{id}/delete)
	DeleteUnassignedEntry(w http.ResponseWriter, r *http.Request, id EntryId)
	// DownloadUnassignedEntry Download an entry of No asignados (RF-27)
	// (GET /unassigned/{id}/download)
	DownloadUnassignedEntry(w http.ResponseWriter, r *http.Request, id EntryId)
	// DeleteUnassignedFile Delete one file of an entry of No asignados for good (RF-27, RF-30)
	// (POST /unassigned/{id}/files/delete)
	DeleteUnassignedFile(w http.ResponseWriter, r *http.Request, id EntryId)
	// DownloadUnassignedFile Download one file of No asignados with HTTP Range support (RF-27)
	// (GET /unassigned/{id}/files/download)
	DownloadUnassignedFile(w http.ResponseWriter, r *http.Request, id EntryId, params DownloadUnassignedFileParams)
	// TrashUnassignedFile Send one file of an entry of No asignados to the trash (RF-27, RF-30)
	// (POST /unassigned/{id}/files/trash)
	TrashUnassignedFile(w http.ResponseWriter, r *http.Request, id EntryId)
	// ReleaseAssignLock Cancel the assignment of an entry (RF-26)
	// (DELETE /unassigned/{id}/lock)
	ReleaseAssignLock(w http.ResponseWriter, r *http.Request, id EntryId, params ReleaseAssignLockParams)
	// TakeAssignLock Open the assignment of an entry of No asignados (RF-26)
	// (POST /unassigned/{id}/lock)
	TakeAssignLock(w http.ResponseWriter, r *http.Request, id EntryId, params TakeAssignLockParams)
	// PlanAssign Preview the assignment of an entry (RF-24, RF-25)
	// (POST /unassigned/{id}/plan)
	PlanAssign(w http.ResponseWriter, r *http.Request, id EntryId, params PlanAssignParams)
	// GetAssignSuggestions What each file of the entry is, and its best TMDB match (RF-20, RF-23)
	// (GET /unassigned/{id}/suggestions)
	GetAssignSuggestions(w http.ResponseWriter, r *http.Request, id EntryId, params GetAssignSuggestionsParams)
	// TrashUnassignedEntry Send an entry of No asignados to the trash (RF-27, RF-30)
	// (POST /unassigned/{id}/trash)
	TrashUnassignedEntry(w http.ResponseWriter, r *http.Request, id EntryId)
}

